context.allRecords = ca.getContentRecords()

con:config.script:
def authorTime = '/urn:careContact/urn1:careContactHeader/urn1:accountableHealthcareProfessional/urn1:authorTime'
def start = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:start'
def end = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:end'
def dateFormat = 'yyyyMMdd'

if (!context.allRecords) {
	testRunner.fail("No records")
	return
}
if (!context.dates) {
	def authorTimes = context.allRecords.collect { record -> record.firstElementAt(authorTime) }
	def startTimes = context.allRecords.collect { record -> record.firstElementAt(start) }
	def endTimes = context.allRecords.collect { record -> record.firstElementAt(end) }
	def dates = (authorTimes + startTimes + endTimes).findAll().collect { it[0..7] }.unique()

	def firstDate = Date.parse(dateFormat, dates.min())
	def lastDate = Date.parse(dateFormat, dates.max())
	def dateDiff = lastDate - firstDate
	context.dates =  []
	(2 * context.numberOfIntervals.toInteger()).times {
		def randomOffset = (Math.random() * (dateDiff+1)).toInteger()
		def randomDate = firstDate.plus(randomOffset).format(dateFormat)
		context.dates.add(randomDate)
	}
}

def dates = [context.dates.pop(), context.dates.pop()].sort()
context.timePeriodStart = dates[0]
context.timePeriodEnd = dates[-1]

[context.timePeriodStart, context.timePeriodEnd]

con:configuration.scriptText:
import se.skl.rivta.tksupport.soapui.ContentAssertions
def ca = new ContentAssertions(context, messageExchange, log)
ca.assertSchematronConstraints()

import se.skl.rivta.tksupport.soapui.ContentAssertions
def ca = new ContentAssertions(context, messageExchange)

def authorTime = '/urn:careContact/urn1:careContactHeader/urn1:accountableHealthcareProfessional/urn1:authorTime'
def start = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:start'
def end = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:end'
def id = '/urn:careContact/urn1:careContactHeader/urn1:documentId'

def condition = { record ->
	def authorTimeWithin = record.timestampIsBefore(authorTime, context.timePeriodEnd + '235959') && record.timestampIsAfter(authorTime, context.timePeriodStart + '000000')
	def startTimeWithin = record.timestampIsBefore(authorTime, context.timePeriodEnd + '235959') && record.timestampIsAfter(authorTime, context.timePeriodStart + '000000')
	def before = [end].every { record.timestampIsBefore(it, context.timePeriodStart) }
	def after = [start].every { record.timestampIsAfter(it, context.timePeriodEnd) }
	def contactTimeWithin = !before && !after
	return (authorTimeWithin || contactTimeWithin)
}

def recordInfo = { record ->
	sprintf("DocumentId %s (authorTime:%s start:%s end:%s)", [id, authorTime, start, end].collect{record.firstElementAt(it)})
}

ca.assertFilteredResponse(context.allRecords, condition, recordInfo)

