ca.assertSchematronConstraints()

import se.skl.rivta.tksupport.soapui.ContentAssertions
def ca = new ContentAssertions(context, messageExchange, log)
def today = new Date(System.currentTimeMillis()).format('YYYYMMdd')
def startDate = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:start'
def endDate = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:end'
ca.assertForAnyRecord({ record -> 
   record.firstElementAt(startDate)[0..7] < today && 
   record.firstElementAt(endDate) == null
   },
   "At least one record must contain a careContactTimePeriod/start in the past and no careContactTimePeriod/end"
)

