con:configuration.scriptText:
import se.skl.rivta.tksupport.soapui.ContentAssertions
def ca = new ContentAssertions(context, messageExchange, log)
ca.assertSchematronConstraints()

import se.skl.rivta.tksupport.soapui.ContentAssertions
def ca = new ContentAssertions(context, messageExchange)

def authorTime = '/urn:careContact/urn1:careContactHeader/urn1:accountableHealthcareProfessional/urn1:authorTime'
def start = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:start'
def end = '/urn:careContact/urn1:careContactBody/urn1:careContactTimePeriod/urn1:end'
def id = '/urn:careContact/urn1:careContactHeader/urn1:documentId'


def condition = { record ->
	def hasAuthorTime = record.firstElementAt(authorTime)
	def hasCareContactStart = record.firstElementAt(start)
	def hasCareContactEnd = record.firstElementAt(end)
	log.info("hasAuthorTime:" + hasAuthorTime)
	log.info("hasCareContactStart:" + hasCareContactStart)
	log.info("hasCareContactEnd:" + hasCareContactEnd)
	return hasAuthorTime && hasAuthorTime[0..7] != hasCareContactStart[0..7] && (!hasCareContactEnd || hasAuthorTime[0..7] != hasCareContactEnd[0..7])
}

def recordInfo = sprintf("Testdata saknas där registreringsdatum är unikt")

ca.assertForAnyRecord(condition, recordInfo)

